package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TokenBuffer_writeNumber_TriageGen2Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteNumber_PositiveFloat() throws IOException {
        float value = 123.45f;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(123.45f, parser.getFloatValue(), 0.0001f);
    }

    @Test
    public void testWriteNumber_NegativeFloat() throws IOException {
        float value = -123.45f;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(-123.45f, parser.getFloatValue(), 0.0001f);
    }

    @Test
    public void testWriteNumber_Zero() throws IOException {
        float value = 0.0f;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(0.0f, parser.getFloatValue(), 0.0f);
    }

    @Test
    public void testWriteNumber_Infinity() throws IOException {
        float value = Float.POSITIVE_INFINITY;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        // Jackson typically handles Infinity as a specific token or value
        Assert.assertEquals(Float.POSITIVE_INFINITY, parser.getFloatValue());
    }

    @Test
    public void testWriteNumber_NaN() throws IOException {
        float value = Float.NaN;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        Assert.assertTrue(Float.isNaN(parser.getFloatValue()));
    }

    @Test
    public void testWriteNumber_SmallValue() throws IOException {
        float value = 1.23E-10f;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(value, parser.getFloatValue(), 0.0);
    }

    @Test
    public void testWriteNumber_LargeValue() throws IOException {
        float value = 1.23E+10f;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(value, parser.getFloatValue(), 0.0);
    }

    @Test
    public void testWriteNumber_WithCodec() throws IOException {
        // Test with a secondary codec to ensure it respects the buffer context
        ObjectMapper specializedMapper = new ObjectMapper();
        specializedMapper.enable(SerializationFeature.WRITE_BIGDECIMAL_AS_FLOAT);
        TokenBuffer bufferWithCodec = new TokenBuffer(specializedMapper);

        float value = 3.14f;
        bufferWithCodec.writeNumber(value);

        JsonParser parser = bufferWithCodec.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(value, parser.getFloatValue(), 0.0001f);
    }
}
